import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Pi 深度解析：极简内核的 Coding Agent","description":"","frontmatter":{"title":"Pi 深度解析：极简内核的 Coding Agent","sidebar":"auto","date":"2026-09-26T00:00:00.000Z","isComment":true,"categories":["AI","Agent"],"tags":["Pi","Coding Agent","TypeScript"]},"headers":[],"relativePath":"pi-ai/index.md","filePath":"pi-ai/index.md","lastUpdated":1790425174000}'),n={name:"pi-ai/index.md"};function o(d,e,p,l,g,s){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="pi-深度解析-极简内核的-coding-agent" tabindex="-1">Pi 深度解析：极简内核的 Coding Agent <a class="header-anchor" href="#pi-深度解析-极简内核的-coding-agent" aria-label="Permalink to &quot;Pi 深度解析：极简内核的 Coding Agent&quot;">​</a></h1><blockquote><p>Pi 是 <a href="https://github.com/badlogic/pi-mono" target="_blank" rel="noreferrer">OpenClaw</a> 底层的 coding agent，由 Mario Zechner 开发（MIT 协议）。与「大而全」的框架相反，它的核心只有 4 个工具（read/write/edit/bash），一切复杂能力都靠 <strong>TypeScript 扩展</strong> 在运行时注入。本系列基于源码与 <a href="https://pi.dev" target="_blank" rel="noreferrer">pi.dev</a> 文档，拆解它的四层架构、事件驱动循环与可扩展性设计，并用 <code>examples/06-pi-agent</code> 把 pi-agent-core 接到本地 Ollama。</p></blockquote><hr><h2 id="这套系列学什么" tabindex="-1">这套系列学什么 <a class="header-anchor" href="#这套系列学什么" aria-label="Permalink to &quot;这套系列学什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇</th><th>主题</th><th>关键问题</th></tr></thead><tbody><tr><td><a href="./01-architecture">01 架构拆解</a></td><td>四层 monorepo + 事件驱动 loop</td><td>pi-ai / pi-agent-core / pi-coding-agent 各管什么？事件流怎么驱动 UI？</td></tr><tr><td><a href="./02-extensibility">02 可扩展性</a></td><td>扩展、Skills、Prompt 模板、Packages</td><td>为什么核心可以只有 4 个工具？</td></tr><tr><td><a href="./03-sdk-embedding">03 SDK 嵌入</a></td><td>createAgentSession + 自定义 provider</td><td>怎么把 Pi 嵌进自己的应用？怎么接 Ollama？</td></tr></tbody></table><p>配套实验：<a href="https://github.com/jeek/ai-lab/tree/main/examples/06-pi-agent" target="_blank" rel="noreferrer">examples/06-pi-agent</a> —— 用 pi-agent-core + Ollama（gemma4）跑通「工具调用 → 结果回传 → 流式回答」的最小 agent，含 mock streamFn 的单测与真实模型集成测试。</p><h2 id="为什么值得看-pi" tabindex="-1">为什么值得看 Pi <a class="header-anchor" href="#为什么值得看-pi" aria-label="Permalink to &quot;为什么值得看 Pi&quot;">​</a></h2><p>2025-2026 年 coding agent 爆发（Claude Code、Codex CLI、OpenClaw……），大多数是「配置驱动」：JSON/YAML 声明行为。Pi 走另一条路——<strong>代码即配置</strong>，扩展就是普通 TypeScript 模块，热重载、可测试、可发布成 npm 包。对前端开发者来说，这是理解「agent 内核到底需要多小」的绝佳样本。</p>',8)])])}const m=t(n,[["render",o]]);export{h as __pageData,m as default};
